import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class ClassX {
    /**
     * Extrae un miembro específico de un archivo (simulado).
     * 
     * La función verifica si el nombre del miembro comienza con una barra diagonal para prevenir rutas absolutas.
     * 
     * @param filePath Ruta del archivo del que se quiere extraer el miembro.
     * @param memberName Nombre del miembro a extraer.
     * @return Contenido del miembro o null si no se encuentra o si es una ruta absoluta.
     */
    public String extractMember(String filePath, String memberName) {
        if (memberName.startsWith("/")) {
            return null; // Prevenir rutas absolutas
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(new File(filePath)))) {
            String line;
            boolean isMemberFound = false;
            while ((line = br.readLine()) != null) {
                if (line.contains(memberName)) {
                    isMemberFound = true;
                }
                if (isMemberFound) {
                    content.append(line).append(System.lineSeparator());
                    if (line.trim().isEmpty()) { // Asumiendo que hay una línea vacía después del miembro
                        break;
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
        return content.toString().isEmpty() ? null : content.toString();
    }
}
