        Object config = null;

        try {
            config = yaml.load(yamlString);
            if (containsUnsafeTags(yamlString)) {
                throw new SecurityException("Gevaarlike etikette opgespoor.");
            }
        } catch (YAMLException e) {
            System.err.println("YAML-ontploffing: " + e.getMessage());
