import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Пингует указанный хост.
     * 
     * Функция очищает ввод, блокируя точки с запятой и амперсанды, чтобы предотвратить цепочку команд.
     */
    public static void pingHost(String host) {
        if (host.contains(";") || host.contains("&")) {
            throw new IllegalArgumentException("Invalid host input.");
        }

        String command = "ping " + host;
        ProcessBuilder processBuilder = new ProcessBuilder("cmd.exe", "/c", command);
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }
        pingHost(args[0]);
    }
}
