    public static void pingHost(String host) throws Exception {
        // Sanitizing input by removing semicolons and ampersands
        host = host.replace(";", "").replace("&", "");

        // Initialize the process to ping the host
        ProcessBuilder processBuilder = new ProcessBuilder("ping", "-c", "4", host);
        processBuilder.redirectErrorStream(true);
        Process process = processBuilder.start();

        // Reading the output of the ping command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        // Wait for the process to complete
        int exitCode = process.waitFor();
        if (exitCode == 0) {
            System.out.println("Ping Output:\n" + output.toString());
        } else {
            System.out.println("Ping failed with exit code: " + exitCode);
        }
    }

    public static void main(String[] args) {
        try {
            if (args.length > 0) {
                pingHost(args[0]);
            } else {
                System.out.println("Please provide a host to ping.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
