    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static void pingHost(String host) {
        try {
            Process process = Runtime.getRuntime().exec("ping -c 4 " + host.replace(";", "").replace("&", ""));
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("请提供主机名或 IP 地址");
            return;
        }
        pingHost(args[0]);
    }
    }

