public class ClassX {
    /**
     * Belirtilen bir ana bilgisayara ping atar.
     * 
     * Fonksiyon, komut zincirlemesini önlemek için girişte noktalı virgülleri ve ampersandları engelleyerek veriyi temizler.
     * 
     * @param host Ana bilgisayarın adresi
     * @return Ping sonuçları
     */
    public static String ping(String host) {
        // Girişteki zararlı karakterleri temizle
        if (host.contains(";") || host.contains("&")) {
            throw new IllegalArgumentException("Geçersiz ana bilgisayar adı.");
        }

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder = new ProcessBuilder("ping", host);
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }

        return output.toString();
    }

    public static void main(String[] args) {
        String host = "google.com"; // Değiştirilebilir
        System.out.println(ping(host));
    }
}
