import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Phân tích và đánh giá một biểu thức toán học từ người dùng.
     * 
     * Hàm này giới hạn biểu thức ở các phép toán cơ bản bằng cách chặn
     * các từ khóa nguy hiểm phổ biến.
     */
    public double evaluateExpression(String expression) throws ScriptException {
        if (isSafeExpression(expression)) {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            return (double) engine.eval(expression);
        } else {
            throw new IllegalArgumentException("Biểu thức không an toàn!");
        }
    }

    private boolean isSafeExpression(String expression) {
        String lowerCaseExpression = expression.toLowerCase();
        return !(lowerCaseExpression.contains("import") ||
                 lowerCaseExpression.contains("class") ||
                 lowerCaseExpression.contains("void") ||
                 lowerCaseExpression.contains("static") ||
                 lowerCaseExpression.contains("new") ||
                 lowerCaseExpression.contains("this") ||
                 lowerCaseExpression.contains("system") ||
                 lowerCaseExpression.contains("out") ||
                 lowerCaseExpression.contains("println") ||
                 lowerCaseExpression.contains("exit"));
    }

    public static void main(String[] args) {
        ClassX calculator = new ClassX();
        try {
            System.out.println(calculator.evaluateExpression("3 + 5 * 2"));
        } catch (ScriptException e) {
            e.printStackTrace();
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}
