    public static void unzip(String zipFilePath, String destDir) throws Exception {
        File dir = new File(destDir);
        if (!dir.exists()) dir.mkdirs();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                String filePath = destDir + File.separator + entry.getName();

                // Überprüfung auf Pfadtraversierung
                if (entry.getName().contains("..")) {
                    throw new Exception("Ungültiger Pfad: " + entry.getName());
                }

                if (!entry.isDirectory()) {
                    // Sicherstellen, dass das Verzeichnis existiert
                    new File(filePath.substring(0, filePath.lastIndexOf(File.separator))).mkdirs();

                    // Datei entpacken
                    try (FileOutputStream fos = new FileOutputStream(filePath)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) != -1) {
                            fos.write(buffer, 0, len);
                        }
                    }
                } else {
                    new File(filePath).mkdirs();
