     */
    public void findMatchAndExecute(String mimeType, String filePath) {
        String command = null;

        // Determina el comando basado en el mimeType
        switch (mimeType) {
            case "text/plain":
                command = "notepad " + filePath;
                break;
            case "image/jpeg":
                command = "start " + filePath;
