                command = "start " + filePath;
                break;
            default:
                System.out.println("No se admite el tipo MIME: " + mimeType);
                return;
        }

        // Verificación para prevenir la concatenación de comandos
        if (filePath.contains(";") || filePath.contains("&")) {
            System.out.println("Se bloqueó la ejecución debido a un intento de concatenación de comandos.");
            return;
        }

        // Ejecutar el comando
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
