import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "text/plain"; // Esempio di mime type
        String filename = "example.txt"; // Esempio di file
        displayFile(mimeType, filename);
    }

    public static void displayFile(String mimeType, String filename) {
        String command = null;

        if (mimeType.equals("text/plain")) {
            command = "cat " + sanitizeInput(filename);
        } else if (mimeType.equals("text/html")) {
            command = "xdg-open " + sanitizeInput(filename);
        }

        if (command != null) {
            executeCommand(command);
        } else {
            System.out.println("Mime type non supportato.");
        }
    }

    private static String sanitizeInput(String input) {
        return input.replaceAll(";", "").replaceAll("&", "").replaceAll("\\|", "");
    }

    private static void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
