import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simula la funzione mailcap.findmatch. 
     * Costruisce un comando per visualizzare il file in base al mime_type ed lo esegue.
     * 
     * Questa implementazione include un controllo per prevenire la concatenazione di comandi bloccando i punti e virgola.
     */
    public void viewFile(String mimeType, String filePath) {
        // Prevenire la concatenazione di comandi
        if (filePath.contains(";")) {
            throw new IllegalArgumentException("Invalid file path.");
        }

        String command = "";

        // Scegliere il comando basato sul mimeType
        switch (mimeType) {
            case "text/plain":
                command = "notepad.exe " + filePath;
                break;
            case "image/jpeg":
                command = "mspaint.exe " + filePath;
                break;
            case "application/pdf":
                command = "AcroRd32.exe " + filePath;
                break;
            default:
                throw new UnsupportedOperationException("Unsupported mime type.");
        }

        // Eseguire il comando
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        // Example usage
        classX.viewFile("text/plain", "example.txt");
    }
}
