import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * 在验证主机后，从生成的 URL 获取内容。
     * 
     * 此函数通过检查空格等无效字符来清理主机。
     */
    public String fetchContent(String host) throws Exception {
        if (host == null || host.trim().isEmpty() || host.contains(" ")) {
            throw new IllegalArgumentException("无效的主机名");
        }

        URL url = new URL("http://" + host);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("请求失败，HTTP响应代码: " + connection.getResponseCode());
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }

        in.close();
        connection.disconnect();

        return content.toString();
    }
}
