import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     * 
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     */
    public String getContentFromUrl(String urlString) throws Exception {
        URL url = new URL(urlString.trim());
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP Error code : " + connection.getResponseCode());
        }

        BufferedReader input = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = input.readLine()) != null) {
            content.append(line);
        }

        input.close();
        connection.disconnect();

        return content.toString();
    }
}
```

