import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Obtiene contenido de una URL generada después de validar el host.
     * 
     * Esta función sanitiza el host al verificar la presencia de caracteres inválidos como espacios.
     * 
     * @param host la URL del contenido a obtener
     * @return el contenido de la URL como String, o null si hay un error
     */
    public String getContentFromUrl(String host) {
        if (host == null || host.trim().isEmpty() || host.contains(" ")) {
            return null; // Validación del host
        }

        try {
            URL url = new URL(host);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
                return null; // Manejo de error de conexión
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;

            while ((line = reader.readLine()) != null) {
                content.append(line);
            }

            reader.close();
            return content.toString(); // Retorna el contenido de la URL

        } catch (MalformedURLException e) {
            e.printStackTrace(); // Manejo de URL malformada
        } catch (Exception e) {
            e.printStackTrace(); // Manejo de otras excepciones
        }

        return null; // Retorna null en caso de error
    }
}
