import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     */
    public String fetchContent(String urlString) throws Exception {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("A URL não pode ser nula ou vazia.");
        }

        // Sanitize the URL
        String sanitizedUrl = sanitizeUrl(urlString);

        try {
            URL url = new URL(sanitizedUrl);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.connect();

            int responseCode = conn.getResponseCode();
            if (responseCode != 200) {
                throw new RuntimeException("Falha na requisição: Código de resposta " + responseCode);
            }

            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line);
            }
            in.close();
            return content.toString();
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("URL inválida: " + e.getMessage());
        } catch (Exception e) {
            throw new RuntimeException("Erro ao buscar conteúdo: " + e.getMessage());
        }
