     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     * 
     * @param host Die URL, von der Inhalte abgerufen werden sollen.
     * @return Der Inhalt der URL als String.
     * @throws Exception Bei Fehlern in der URL oder beim Abrufen der Inhalte.
     */
    public String fetchContent(String host) throws Exception {
        String cleanedHost = cleanHost(host);
        URL url = new URL(cleanedHost);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = in.readLine()) != null) {
            content.append(line);
        }

        in.close();
        return content.toString();
    }

    private String cleanHost(String host) throws MalformedURLException {
        if (host == null || host.trim().isEmpty()) {
            throw new MalformedURLException("Ungültige URL: Leer oder null.");
        }
        String trimmedHost = host.trim();
        if (trimmedHost.contains(" ")) {
            trimmedHost = trimmedHost.replaceAll(" ", "%20");
        }
        return trimmedHost;
    }

